  },

  // 顶级料理（烹饪技能 81+）
  {
    id: "beef_stir_fry",
    name: "黑椒牛柳",
    icon: "🥩",
    minSkill: 81,
    ingredients: [
      { id: "beef", qty: 2 },
      { id: "green_veg", qty: 1 },
      { id: "soy_sauce", qty: 1 },
    ],
    effects: { hunger: -80, happiness: +25, energy: +30, protein: +15 },
    cookTime: 15,
    desc: "顶级享受，肉质鲜嫩。",
  },
  {
    id: "hot_pot",
    name: "火锅",
    icon: "🍲",
    minSkill: 80,
    ingredients: [
      { id: "beef", qty: 2 },
      { id: "pork", qty: 1 },
      { id: "green_veg", qty: 2 },
      { id: "potato", qty: 1 },
      { id: "chili", qty: 2 },
    ],
    effects: { hunger: -90, happiness: +35, energy: +30 },
    cookTime: 20,
    desc: "亲朋好友围坐，热气腾腾。",
  },
];

/** 食材分类 */
const INGREDIENT_CATEGORIES = {
  grain: { name: "主食", icon: "🌾" },
  vegetable: { name: "蔬菜", icon: "🥬" },
  meat: { name: "肉类", icon: "🥩" },
  protein: { name: "蛋白", icon: "🥚" },
  condiment: { name: "调料", icon: "🧂" },
  fruit: { name: "水果", icon: "🍎" },
};

/** 获取食材定义 */
function getIngredient(ingredientId) {
  return INGREDIENTS.find((i) => i.id === ingredientId);
}

/** 获取所有食材 */
function getAllIngredients() {
  return INGREDIENTS;
}

/** 获取所有配方 */
function getAllRecipes() {
  return RECIPES;
}

/** 获取单个配方 */
function getRecipe(recipeId) {
  return RECIPES.find((r) => r.id === recipeId);
}

/** 获取可用配方（根据烹饪技能和现有食材） */
function getAvailableRecipes(state) {
  const cookingLevel = state.skills?.cooking?.level || 0;
  const inventory = state.inventory?.ingredients || {};

  return RECIPES.filter((recipe) => {
    if (recipe.minSkill > cookingLevel) return false;
    // 检查食材是否足够
    for (const ing of recipe.ingredients) {
      const haveQty = inventory[ing.id]?.qty || 0;
      if (haveQty < ing.qty) return false;
    }
    return true;
  });
}

/** 检查食材是否过期 */
function isIngredientExpired(ingredient, buyDay) {
  const def = getIngredient(ingredient.id);
  if (!def) return true;
  const state = StateManager?.getState?.();
  if (!state) return true;
  return state.player.day - buyDay > def.shelfLife;
}

// 全局导出
if (typeof window !== "undefined") {
  Object.assign(window, {
    INGREDIENTS,
    INGREDIENT_CATEGORIES,
    RECIPES,
    getIngredient,
    getRecipe,
    getAllIngredients,
    getAllRecipes,
    getAvailableRecipes,
    isIngredientExpired,
  });
}

