291	/** 计算当前负重状态 */
292	function calcEncumbrance(state) {
293	  const totalWeight = calcInventoryWeight(state);
294	  const maxCarry = calcMaxCarryWeight(state);
295	  const ratio = maxCarry > 0 ? totalWeight / maxCarry : 0;
296	
297	  let tier = ENCUMBRANCE_TIERS[0];
298	  for (const t of ENCUMBRANCE_TIERS) {
299	    if (ratio <= t.maxRatio) {
300	      tier = t;
301	      break;
302	    }
303	    tier = t;
304	  }
305	
306	  return {
307	    totalWeight: Math.round(totalWeight * 10) / 10,
308	    maxCarry: Math.round(maxCarry * 10) / 10,
309	    ratio: Math.round(ratio * 100) / 100,
310	    tier,
311	    totalVolume: Math.round(calcInventoryVolume(state) * 10) / 10,
312	    maxVolume: Math.round(calcMaxCarryVolume(state) * 10) / 10,
313	  };
314	}
315	
316	/** 计算背包中商品总重量 */
317	function calcInventoryWeight(state) {
318	  let w = 0;
319	  for (const item of state.inventory.items) {
320	    const phys = getGoodPhysics(item.id);
321	    w += phys.weight * item.qty;
322	  }
323	  // 容器自重
324	  const containers = state.inventory.containers || [];
325	  for (const c of containers) {
326	    const typeDef = getContainerType(c.containerId);
327	    w += typeDef.selfWeight;
328	  }
329	  return w;
330	}
331	
332	/** 计算背包中商品总体积 */
333	function calcInventoryVolume(state) {
334	  let v = 0;
335	  for (const item of state.inventory.items) {
336	    const phys = getGoodPhysics(item.id);
337	    v += phys.volume * item.qty;
338	  }
339	  const containers = state.inventory.containers || [];
340	  for (const c of containers) {
341	    const typeDef = getContainerType(c.containerId);
342	    v += typeDef.selfVolume;
343	  }
344	  return v;
345	}
346	
347	/** 计算最大可携带重量（基础+体质加成+容器减免） */
348	function calcMaxCarryWeight(state) {
349	  // 基础承重 = 15 + 体质×0.3
350	  let base = 15 + (state.player.physique || 20) * 0.3;
351	
352	  // 容器减负效果
353	  const containers = state.inventory.containers || [];
354	  for (const c of containers) {
355	    const typeDef = getContainerType(c.containerId);
356	    if (typeDef.weightReduction > 0) {
357	      // 减负容器：背包容器内的物品重量按减免率计算
358	      // 简化处理：直接增加有效承重
359	      base += typeDef.capacity * typeDef.weightReduction * 0.3;
360	    }
361	  }
362	
363	  return base;
364	}
365	
366	/** 计算最大可携带体积 */
367	function calcMaxCarryVolume(state) {
368	  let base = 12; // 徒手基础体积
369	
370	  const containers = state.inventory.containers || [];
371	  for (const c of containers) {
372	    const typeDef = getContainerType(c.containerId);
373	    base += typeDef.volumeCapacity;
374	  }
375	
376	  return base;
377	}
