391	/** 检查能否放入更多商品 */
392	function canCarryMore(state, goodId, qty) {
393	  const phys = getGoodPhysics(goodId);
394	  const addedWeight = phys.weight * qty;
395	  const addedVolume = phys.volume * qty;
396	  const currentWeight = calcInventoryWeight(state);
397	  const currentVolume = calcInventoryVolume(state);
398	  const maxWeight = calcMaxCarryWeight(state);
399	  const maxVolume = calcMaxCarryVolume(state);
400	
401	  // 允许超载到1.6倍（极限），但给出警告
402	  return {
403	    weightOk: currentWeight + addedWeight <= maxWeight * 1.6,
404	    volumeOk: currentVolume + addedVolume <= maxVolume * 1.6,
405	    weightRatio: (currentWeight + addedWeight) / maxWeight,
406	    volumeRatio: (currentVolume + addedVolume) / maxVolume,
407	    overLimit:
408	      currentWeight + addedWeight > maxWeight ||
409	      currentVolume + addedVolume > maxVolume,
410	  };
411	}
