461	/** 雇佣运输——将指定商品从当前地点运到目标地点 */
462	function hireTransport(serviceId, goods, destKey) {
463	  const state = StateManager.getState();
464	  const service = getTransportService(serviceId);
465	  if (!service) {
466	    StateManager.addMessage("⚠️ 不存在的运输服务。", "danger");
467	    return false;
468	  }
469	
470	  // 检查目标地点是否可达
471	  const reachable = getReachableLocations(state.trade.currentLocation);
472	  if (!reachable.includes(destKey)) {
473	    StateManager.addMessage("⚠️ 该地点无法直接到达。", "danger");
474	    return false;
475	  }
476	
477	  // 计算运费
478	  let totalQty = 0;
479	  let totalWeight = 0;
480	  let totalVolume = 0;
481	  let totalValue = 0;
482	  const toShip = []; // { id, qty, good }
483	
484	  for (const { goodId, qty } of goods) {
485	    const good = getGoodById(goodId);
486	    if (!good) continue;
487	    const inv = state.inventory.items.find((i) => i.id === goodId);
488	    if (!inv || inv.qty < qty) {
489	      StateManager.addMessage(`⚠️ 背包中${good.name}不足。`, "danger");
490	      return false;
491	    }
492	    const phys = getGoodPhysics(goodId);
493	    totalQty += qty;
494	    totalWeight += phys.weight * qty;
495	    totalVolume += phys.volume * qty;
496	    const price = getCurrentPrice(state.trade.currentLocation, goodId);
497	    totalValue += price * qty;
498	    toShip.push({ id: goodId, qty, good });
499	  }
500	
501	  if (totalQty === 0) {
502	    StateManager.addMessage("⚠️ 没有需要运输的货物。", "danger");
503	    return false;
504	  }
505	
506	  // 检查运输容量
507	  if (totalWeight > service.capacity || totalVolume > service.volumeCapacity) {
508	    StateManager.addMessage(
509	      `⚠️ ${service.name}装不下这么多货物！重量${Math.round(totalWeight)}/${service.capacity}，体积${Math.round(totalVolume)}/${service.volumeCapacity}`,
510	      "danger",
511	    );
512	    return false;
513	  }
514	
515	  // 检查现金
516	  if (state.resources.cash < service.cost) {
517	    StateManager.addMessage(`⚠️ 运费¥${service.cost}，现金不足。`, "danger");
518	    return false;
519	  }
520	
521	  // 消耗AP
522	  if (!consumeAP(AP_COSTS.check_investment)) return false;
523	
524	  // 扣运费
525	  state.resources.cash -= service.cost;
526	
527	  // 从背包中移除货物
528	  for (const { id, qty } of toShip) {
529	    const inv = state.inventory.items.find((i) => i.id === id);
530	    inv.qty -= qty;
531	    if (inv.qty <= 0) {
532	      state.inventory.items = state.inventory.items.filter((i) => i.id !== id);
533	    }
534	  }
535	
536	  // 运输随机事件
537	  let events = [];
538	
539	  // 1. 偷窃事件
540	  if (Random.chance(service.theftRisk / 100)) {
541	    // 随机偷走10-30%的某一种货物
542	    const targetGood = Random.fromArray(toShip);
543	    const stolenRatio = Random.float(0.1, 0.3);
544	    const stolenQty = Math.max(1, Math.floor(targetGood.qty * stolenRatio));
545	    targetGood.qty -= stolenQty;
546	    const good = getGoodById(targetGood.id);
