649	  if (arrivedQty > 0) {
650	    StateManager.addMessage(
651	      `📦 ${arrivedQty}件货物已到达${destName}，可从当地仓库取出。`,
652	      "success",
653	    );
654	  }
655	
656	  return true;
657	}
