659	/** 从当地仓库取出货物到背包 */
660	function retrieveFromStorage(goodId, qty) {
661	  const state = StateManager.getState();
662	  const locKey = state.trade.currentLocation;
663	  const storage = state.inventory.storage?.[locKey];
664	  if (!storage) {
665	    StateManager.addMessage("⚠️ 当地没有暂存货物。", "warning");
666	    return false;
667	  }
668	
669	  const stored = storage.find((i) => i.id === goodId);
670	  if (!stored || stored.qty < qty) {
671	    const good = getGoodById(goodId);
672	    StateManager.addMessage(
673	      `⚠️ 仓库中${good ? good.name : goodId}不足。`,
674	      "danger",
675	    );
676	    return false;
677	  }
678	
679	  // 检查能否背得动
680	  const carry = canCarryMore(state, goodId, qty);
681	  if (carry.overLimit && carry.weightRatio > 1.6) {
682	    StateManager.addMessage("⚠️ 太重了！背不动这么多。", "danger");
683	    return false;
684	  }
685	
686	  // 移到背包
687	  const good = getGoodById(goodId);
688	  const existing = state.inventory.items.find((i) => i.id === goodId);
689	  if (existing) {
690	    existing.qty += qty;
691	  } else {
692	    state.inventory.items.push({
693	      id: goodId,
694	      qty,
695	      avgBuyPrice: stored.avgBuyPrice || good.basePrice,
696	    });
697	  }
698	
699	  // 从仓库移除
700	  stored.qty -= qty;
701	  if (stored.qty <= 0) {
702	    state.inventory.storage[locKey] = storage.filter((i) => i.id !== goodId);
703	  }
704	
705	  StateManager.addMessage(
706	    `📦 从仓库取出${qty}${good.unit}${good.name}。`,
707	    "success",
708	  );
709	  return true;
710	}
711	
712	// ====== 容器装备系统 ======
713	
714	/** 购买并装备容器 */
715	function buyContainer(containerId) {
716	  const state = StateManager.getState();
717	  const typeDef = getContainerType(containerId);
718	  if (!typeDef || containerId === "none") {
719	    StateManager.addMessage("⚠️ 不存在的容器。", "danger");
720	    return false;
721	  }
722	
723	  if (state.resources.cash < typeDef.price) {
724	    StateManager.addMessage(`⚠️ 需要¥${typeDef.price}，现金不足。`, "danger");
725	    return false;
726	  }
727	
728	  if (!consumeAP(AP_COSTS.buy_backpack)) return false;
729	
730	  // 检查是否已有同槽位容器
731	  if (!state.inventory.containers) state.inventory.containers = [];
732	  const existing = state.inventory.containers.find(
733	    (c) => c.slot === typeDef.slot,
734	  );
735	  if (existing && existing.containerId === containerId) {
736	    StateManager.addMessage("⚠️ 你已经有一个了。", "warning");
737	    return false;
738	  }
739	
740	  state.resources.cash -= typeDef.price;
741	
742	  if (existing) {
743	    // 替换旧容器
744	    StateManager.addMessage(
745	      `🎒 换下了${getContainerType(existing.containerId).name}，装备了${typeDef.name}。`,
746	      "info",
747	    );
748	    existing.containerId = containerId;
749	  } else {
750	    state.inventory.containers.push({ containerId, slot: typeDef.slot });
751	    StateManager.addMessage(
752	      `🎒 购买了${typeDef.name}！容量+${typeDef.capacity}，减负${Math.round(typeDef.weightReduction * 100)}%。`,
753	      "success",
754	    );
755	  }
756	
757	  return true;
758	}
