760	// ====== 易腐商品变质系统 ======
761	
762	/** 每日检查商品变质 */
763	function tickPerishableGoods(state) {
764	  if (!state.inventory.items) return;
765	  let spoiled = [];
766	
767	  for (const item of state.inventory.items) {
768	    const phys = getGoodPhysics(item.id);
769	    if (!phys.perishable) continue;
770	
771	    // 初始化购入日期
772	    if (!item.buyDay) item.buyDay = state.player.day;
773	
774	    const daysHeld = state.player.day - item.buyDay;
775	    if (phys.shelfLife && daysHeld >= phys.shelfLife) {
776	      // 商品变质
777	      const good = getGoodById(item.id);
778	      spoiled.push(`${good.name}×${item.qty}`);
779	    }
780	  }
781	
782	  // 移除变质商品
783	  state.inventory.items = state.inventory.items.filter((item) => {
784	    const phys = getGoodPhysics(item.id);
785	    if (!phys.perishable) return true;
786	    if (!item.buyDay) {
787	      item.buyDay = state.player.day;
788	      return true;
789	    }
790	    const daysHeld = state.player.day - item.buyDay;
791	    return !phys.shelfLife || daysHeld < phys.shelfLife;
792	  });
793	
794	  // 同样检查各地仓库
795	  if (state.inventory.storage) {
796	    for (const locKey of Object.keys(state.inventory.storage)) {
797	      state.inventory.storage[locKey] = state.inventory.storage[locKey].filter(
798	        (item) => {
799	          const phys = getGoodPhysics(item.id);
800	          if (!phys.perishable) return true;
801	          if (!item.buyDay) {
802	            item.buyDay = state.player.day;
803	            return true;
804	          }
805	          const daysHeld = state.player.day - item.buyDay;
806	          return !phys.shelfLife || daysHeld < phys.shelfLife;
807	        },
808	      );
809	    }
810	  }
811	
812	  if (spoiled.length > 0) {
813	    StateManager.addMessage(
814	      `🗑️ 以下商品已变质被丢弃：${spoiled.join("、")}`,
815	      "warning",
816	    );
817	    state.needs.happiness = Math.max(0, state.needs.happiness - 3);
818	  }
819	}
820	
821	// ====== 修改买卖函数以适配新系统 ======
822	
823	/** 新版购买商品（考虑重量/体积限制） */
824	function buyGoodV2(goodId, qty) {
825	  const state = StateManager.getState();
826	  const good = getGoodById(goodId);
827	  if (!good) {
828	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
829	    return false;
830	  }
831	
832	  const locKey = state.trade.currentLocation;
833	  const price = getCurrentPrice(locKey, goodId);
834	  const totalCost = Math.round(price * qty * 100) / 100;
835	
836	  // 检查现金
837	  if (state.resources.cash < totalCost) {
838	    StateManager.addMessage(
839	      `⚠️ 钱不够！需要¥${totalCost.toFixed(1)}，你只有¥${state.resources.cash}。`,
840	      "danger",
841	    );
842	    return false;
843	  }
844	
845	  // 检查负重/体积
846	  const carry = canCarryMore(state, goodId, qty);
847	  if (carry.weightRatio > 1.6 || carry.volumeRatio > 1.6) {
848	    StateManager.addMessage("⚠️ 太重/太大了！完全背不动。", "danger");
849	    return false;
850	  }
851	
852	  // 扣钱
853	  state.resources.cash -= totalCost;
854	
855	  // 买卖消耗AP（每笔交易3AP）
856	  if (typeof consumeAP === "function") {
857	    if (!consumeAP(3)) return false;
858	  }
859	
860	  // 加入背包
861	  const existing = state.inventory.items.find((i) => i.id === goodId);
862	  if (existing) {
863	    existing.qty += qty;
864	  } else {
865	    state.inventory.items.push({
866	      id: goodId,
867	      qty,
868	      avgBuyPrice: price,
869	      buyDay: state.player.day,
870	    });
871	  }
872	
873	  // 超载警告
874	  const enc = calcEncumbrance(state);
875	  let warnMsg = "";
876	  if (enc.tier.apPenalty > 0) {
877	    warnMsg = `（负重${enc.tier.name}，行动+${enc.tier.apPenalty}AP）`;
878	  }
879	
880	  StateManager.addMessage(
881	    `🛒 购买了${qty}${good.unit}${good.name}，单价¥${price.toFixed(1)}，共¥${totalCost.toFixed(1)}。${warnMsg}`,
882	    "success",
883	  );
884	
885	  // 记录供需（买入推高当地价格）
886	  if (typeof recordLocalPurchase === "function")
887	    recordLocalPurchase(state, locKey, goodId, qty);
888	
889	  // 买卖影响状态/属性
890	  if (typeof applyTradeEffects === "function") applyTradeEffects(state, true);
891	
892	  // 随机邂逅
893	  if (typeof tryRomanceEncounter === "function") tryRomanceEncounter(state);
894	
895	  return true;
896	}
897	
898	/** 新版卖出商品（记录利润） */
899	function sellGoodV2(goodId, qty) {
900	  const state = StateManager.getState();
901	  const good = getGoodById(goodId);
902	  if (!good) {
903	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
904	    return false;
905	  }
906	
907	  const existing = state.inventory.items.find((i) => i.id === goodId);
908	  if (!existing || existing.qty < qty) {
909	    StateManager.addMessage(`⚠️ 背包中没有足够的${good.name}！`, "danger");
910	    return false;
911	  }
912	
913	  const locKey = state.trade.currentLocation;
914	  const price = getCurrentPrice(locKey, goodId);
915	  const totalEarned = Math.round(price * qty * 100) / 100;
916	
917	  state.resources.cash += totalEarned;
918	  state.resources.totalEarned += totalEarned;
919	
920	  // 买卖消耗AP（每笔交易3AP，卖出时AP不足也允许，但时间仍推进）
921	  if (typeof consumeAP === "function") consumeAP(3);
922	
923	  existing.qty -= qty;
924	  if (existing.qty <= 0) {
925	    state.inventory.items = state.inventory.items.filter(
926	      (i) => i.id !== goodId,
927	    );
928	  }
929	
930	  // 利润计算
931	  const buyPrice = getAvgBuyPrice(state, goodId);
932	  let profitMsg = "";
933	  if (buyPrice > 0) {
934	    const profit = totalEarned - buyPrice * qty;
935	    if (profit > 0) {
936	      profitMsg = ` 📈获利¥${profit.toFixed(1)}！`;
937	    } else if (profit < 0) {
938	      profitMsg = ` 📉亏损¥${Math.abs(profit).toFixed(1)}。`;
939	    }
940	  }
941	
942	  StateManager.addMessage(
943	    `💰 卖出了${qty}${good.unit}${good.name}，单价¥${price.toFixed(1)}，共¥${totalEarned.toFixed(1)}。${profitMsg}`,
944	    "success",
945	  );
946	
947	  // 记录供需（卖出压低当地价格）
948	  if (typeof recordLocalSale === "function")
949	    recordLocalSale(state, locKey, goodId, qty);
950	
951	  // 买卖影响状态/属性
952	  if (typeof applyTradeEffects === "function") applyTradeEffects(state, false);
953	
954	  // 随机邂逅
955	  if (typeof tryRomanceEncounter === "function") tryRomanceEncounter(state);
