1002	    const newTotal = wholesalePrice * qty;
1003	    existing.qty += qty;
1004	    existing.avgBuyPrice =
1005	      Math.round(((oldTotal + newTotal) / existing.qty) * 100) / 100;
1006	  } else {
1007	    state.inventory.items.push({
1008	      id: goodId,
1009	      qty,
1010	      avgBuyPrice: wholesalePrice,
1011	      buyDay: state.player.day,
1012	    });
1013	  }
1014	
1015	  const enc = calcEncumbrance(state);
1016	  let warnMsg = "";
1017	  if (enc.tier.apPenalty > 0) {
1018	    warnMsg = `（负重${enc.tier.name}，行动+${enc.tier.apPenalty}AP）`;
1019	  }
1020	
1021	  StateManager.addMessage(
