/**
 * 背包与运输系统
 *
 * 改进点：
 * - 商品增加重量/体积/易腐属性
 * - 背包容量改为重量+体积双限制
 * - 多层携带：背部+腰带+手持
 * - 负重等级影响AP消耗和移动速度
 * - 雇佣运输：力工/快递/搬家公司
 * - 运输随机事件：偷窃/天气损坏/交通事故
 */

// ====== 商品物理属性扩展 ======
// 为每个商品补充重量、体积、易腐性
const GOOD_PHYSICS = {
  water: {
    weight: 0.5,
    volume: 0.5,
    perishable: false,
    fragile: false,
    tempSensitive: false,
  },
  instant_noodles: {
    weight: 0.2,
    volume: 0.3,
    perishable: false,
    fragile: false,
    tempSensitive: false,
  },
  snacks: {
    weight: 0.15,
    volume: 0.2,
    perishable: true,
    shelfLife: 60,
    fragile: false,
    tempSensitive: false,
  },
  fruits: {
    weight: 0.5,
    volume: 0.6,
    perishable: true,
    shelfLife: 5,
    fragile: true,
    tempSensitive: true,
  },
  vegetables: {
    weight: 0.4,
    volume: 0.5,
    perishable: true,
    shelfLife: 4,
    fragile: true,
    tempSensitive: false,
  },
  beer: {
    weight: 0.6,
    volume: 0.5,
    perishable: false,
    fragile: true,
    tempSensitive: true,
  },
  cigarettes: {
    weight: 0.1,
    volume: 0.1,
    perishable: false,
    fragile: false,
    tempSensitive: false,
  },
  daily_use: {
    weight: 0.3,
    volume: 0.4,
    perishable: false,
    fragile: false,
    tempSensitive: false,
  },
  clothing: {
    weight: 0.4,
    volume: 0.3,
    perishable: false,
    fragile: false,
    tempSensitive: false,
  },
  electronics: {
    weight: 0.8,
    volume: 0.4,
    perishable: false,
    fragile: true,
    tempSensitive: false,
  },
  scrap_metal: {
    weight: 2.0,
    volume: 0.8,
    perishable: false,
    fragile: false,
    tempSensitive: false,
  },
  scrap_paper: {
    weight: 0.3,
    volume: 1.0,
    perishable: false,
    fragile: false,
    tempSensitive: true,
  },
  scrap_plastic: {
    weight: 0.5,
    volume: 0.7,
    perishable: false,
    fragile: false,
    tempSensitive: false,
  },
};

/** 获取商品物理属性 */
function getGoodPhysics(goodId) {
  return (
    GOOD_PHYSICS[goodId] || {
      weight: 0.5,
      volume: 0.5,
      perishable: false,
      fragile: false,
      tempSensitive: false,
    }
  );
}

// ====== 容器定义 ======
// 玩家可装备多个容器，每个容器有重量减免
const CONTAINER_TYPES = [
  {
    id: "none",
    name: "徒手",
    slot: null,
    capacity: 15,
    volumeCapacity: 12,
    weightReduction: 0,
    selfWeight: 0,
    selfVolume: 0,
    price: 0,
    desc: "什么都不带，两只手能拿多少是多少",
  },
  {
    id: "plastic_bag",
    name: "塑料袋",
    slot: "手持",
    capacity: 5,
    volumeCapacity: 8,
    weightReduction: 0.5,
    selfWeight: 0.05,
    selfVolume: 0.1,
    price: 1,
    desc: "超市两毛一个的塑料袋，装不了多少",
  },
  {
    id: "tote_bag",
    name: "帆布袋",
    slot: "手持",
    capacity: 10,
    volumeCapacity: 12,
    weightReduction: 0.7,
    selfWeight: 0.2,
    selfVolume: 0.2,
    price: 8,
    desc: "结实耐用的帆布袋，日常够用",
  },
  {
    id: "small_pack",
    name: "小双肩包",
    slot: "背部",
    capacity: 18,
    volumeCapacity: 16,
    weightReduction: 0.8,
    selfWeight: 0.5,
    selfVolume: 0.3,
    price: 30,
    desc: "学生用的双肩包，轻便实用",
  },
  {
    id: "backpack",
    name: "登山包",
    slot: "背部",
    capacity: 30,
    volumeCapacity: 25,
    weightReduction: 0.9,
    selfWeight: 1.2,
    selfVolume: 0.5,
    price: 80,
    desc: "专业登山包，承重减负，远行必备",
  },
  {
    id: "duffel",
    name: "旅行包",
    slot: "手持",
    capacity: 35,
    volumeCapacity: 30,
    weightReduction: 0.0,
    selfWeight: 1.0,
    selfVolume: 0.6,
    price: 60,
    desc: "大容量旅行包，但没减负，手提很累",
  },
  {
    id: "waist_bag",
    name: "腰包",
    slot: "腰带",
    capacity: 4,
    volumeCapacity: 3,
    weightReduction: 0.95,
    selfWeight: 0.15,
    selfVolume: 0.1,
    price: 15,
    desc: "贴身腰包，贵重物品随身带",
  },
  {
    id: "tool_box",
    name: "工具箱",
    slot: "手持",
    capacity: 12,
    volumeCapacity: 8,
    weightReduction: 0.0,
    selfWeight: 1.5,
    selfVolume: 0.5,
    price: 40,
    desc: "铁皮工具箱，装工具利器，但死沉",
  },
  {
    id: "cart",
    name: "小推车",
    slot: "手持",
    capacity: 60,
    volumeCapacity: 50,
    weightReduction: 0.0,
    selfWeight: 5.0,
    selfVolume: 2.0,
    price: 120,
    desc: "手推板车，搬运大量货物，但推着走很慢",
  },
];

/** 获取容器定义 */
function getContainerType(containerId) {
  return (
    CONTAINER_TYPES.find((c) => c.id === containerId) || CONTAINER_TYPES[0]
  );
}

// ====== 负重等级 ======
const ENCUMBRANCE_TIERS = [
  {
    name: "轻装",
    maxRatio: 0.5,
    movePenalty: 0,
    apPenalty: 0,
    desc: "身轻如燕",
  },
  {
    name: "正常",
    maxRatio: 0.8,
    movePenalty: 0,
    apPenalty: 0,
    desc: "正常负重",
  },
  {
    name: "略重",
    maxRatio: 1.0,
    movePenalty: 0.1,
    apPenalty: 0,
    desc: "背了点东西",
  },
  {
    name: "沉重",
    maxRatio: 1.3,
    movePenalty: 0.2,
    apPenalty: 1,
    desc: "步履沉重",
  },
  {
    name: "超载",
    maxRatio: 1.6,
    movePenalty: 0.4,
    apPenalty: 2,
    desc: "几乎走不动了",
  },
  {
    name: "极限",
    maxRatio: 99,
    movePenalty: 0.6,
    apPenalty: 3,
    desc: "寸步难行！",
  },
];

/** 计算当前负重状态 */
function calcEncumbrance(state) {
  const totalWeight = calcInventoryWeight(state);
  const maxCarry = calcMaxCarryWeight(state);
  const ratio = maxCarry > 0 ? totalWeight / maxCarry : 0;

  let tier = ENCUMBRANCE_TIERS[0];
  for (const t of ENCUMBRANCE_TIERS) {
    if (ratio <= t.maxRatio) {
      tier = t;
      break;
    }
    tier = t;
  }

  return {
    totalWeight: Math.round(totalWeight * 10) / 10,
    maxCarry: Math.round(maxCarry * 10) / 10,
    ratio: Math.round(ratio * 100) / 100,
    tier,
    totalVolume: Math.round(calcInventoryVolume(state) * 10) / 10,
    maxVolume: Math.round(calcMaxCarryVolume(state) * 10) / 10,
  };
}

/** 计算背包中商品总重量 */
function calcInventoryWeight(state) {
  let w = 0;
  for (const item of state.inventory.items) {
    const phys = getGoodPhysics(item.id);
    w += phys.weight * item.qty;
  }
  // 容器自重
  const containers = state.inventory.containers || [];
  for (const c of containers) {
    const typeDef = getContainerType(c.containerId);
    w += typeDef.selfWeight;
  }
  return w;
}

/** 计算背包中商品总体积 */
function calcInventoryVolume(state) {
  let v = 0;
  for (const item of state.inventory.items) {
    const phys = getGoodPhysics(item.id);
    v += phys.volume * item.qty;
  }
  const containers = state.inventory.containers || [];
  for (const c of containers) {
    const typeDef = getContainerType(c.containerId);
    v += typeDef.selfVolume;
  }
  return v;
}

/** 计算最大可携带重量（基础+体质加成+容器减免） */
function calcMaxCarryWeight(state) {
  // 基础承重 = 15 + 体质×0.3
  let base = 15 + (state.player.physique || 20) * 0.3;

  // 容器减负效果
  const containers = state.inventory.containers || [];
  for (const c of containers) {
    const typeDef = getContainerType(c.containerId);
    if (typeDef.weightReduction > 0) {
      // 减负容器：背包容器内的物品重量按减免率计算
      // 简化处理：直接增加有效承重
      base += typeDef.capacity * typeDef.weightReduction * 0.3;
    }
  }

  return base;
}

/** 计算最大可携带体积 */
function calcMaxCarryVolume(state) {
  let base = 12; // 徒手基础体积

  const containers = state.inventory.containers || [];
  for (const c of containers) {
    const typeDef = getContainerType(c.containerId);
    base += typeDef.volumeCapacity;
  }

  return base;
}

/** 获取负重点的AP惩罚 */
function getEncumbranceAPPenalty(state) {
  const enc = calcEncumbrance(state);
  return enc.tier.apPenalty;
}

/** 获取负重点的移动速度惩罚（0-1，0=无惩罚） */
function getEncumbranceMovePenalty(state) {
  const enc = calcEncumbrance(state);
  return enc.tier.movePenalty;
}

/** 检查能否放入更多商品 */
function canCarryMore(state, goodId, qty) {
  const phys = getGoodPhysics(goodId);
  const addedWeight = phys.weight * qty;
  const addedVolume = phys.volume * qty;
  const currentWeight = calcInventoryWeight(state);
  const currentVolume = calcInventoryVolume(state);
  const maxWeight = calcMaxCarryWeight(state);
  const maxVolume = calcMaxCarryVolume(state);

  // 允许超载到1.6倍（极限），但给出警告
  return {
    weightOk: currentWeight + addedWeight <= maxWeight * 1.6,
    volumeOk: currentVolume + addedVolume <= maxVolume * 1.6,
    weightRatio: (currentWeight + addedWeight) / maxWeight,
    volumeRatio: (currentVolume + addedVolume) / maxVolume,
    overLimit:
      currentWeight + addedWeight > maxWeight ||
      currentVolume + addedVolume > maxVolume,
  };
}

