94	/** 计算商品在某地的基准价格修正（不含天气） */
95	function getLocationPriceModifier(locKey, goodId) {
96	  // 1. 地点 priceMod（来自 locations.js 硬编码）
97	  const loc =
98	    typeof getLocation === "function"
99	      ? getLocation(locKey)
