136	  state.trade.supplyDemand[locKey][goodId] += qty;
137	  // 衰减上限：最多影响50%价格
138	  state.trade.supplyDemand[locKey][goodId] = Math.min(
139	    state.trade.supplyDemand[locKey][goodId],
140	    50,
