144	/** 记录玩家在某地卖出了商品（压低当地价格） */
145	function recordLocalSale(state, locKey, goodId, qty) {
146	  if (!state.trade.supplyDemand) state.trade.supplyDemand = {};
147	  if (!state.trade.supplyDemand[locKey]) state.trade.supplyDemand[locKey] = {};
148	  if (!state.trade.supplyDemand[locKey][goodId])
149	    state.trade.supplyDemand[locKey][goodId] = 0;
150	  // 卖出压低价格（供给增加）
151	  state.trade.supplyDemand[locKey][goodId] -= qty;
152	  // 衰减下限：最多影响50%价格
153	  state.trade.supplyDemand[locKey][goodId] = Math.max(
154	    state.trade.supplyDemand[locKey][goodId],
155	    -50,
156	  );
