270	/** 检查并触发市场事件 */
271	function checkMarketEvents(state) {
272	  if (!state.trade.marketEvents) state.trade.marketEvents = [];
273	
274	  // 衰减现有事件
275	  state.trade.marketEvents = state.trade.marketEvents.filter((evt) => {
276	    evt.remaining--;
277	    return evt.remaining > 0;
278	  });
279	
280	  // 随机触发新事件
281	  const season =
282	    typeof getSeason === "function" ? getSeason(state.player.day) : "spring";
283	  for (const template of MARKET_EVENTS) {
284	    // 检查季节限制
285	    if (template.season && !template.season.includes(season)) continue;
286	    // 检查是否已有同类事件
287	    if (state.trade.marketEvents.find((e) => e.id === template.id)) continue;
288	    // 概率触发
289	    if (Random.chance(template.prob)) {
290	      state.trade.marketEvents.push({
291	        id: template.id,
292	        name: template.name,
293	        goodId: template.goodId,
294	        priceMod: template.priceMod,
295	        remaining: template.duration,
296	        desc: template.desc,
297	      });
