303	/** 获取市场事件对某商品的价格修正 */
304	function getMarketEventPriceMod(state, goodId) {
305	  if (!state.trade.marketEvents) return 1.0;
306	  let mod = 1.0;
307	  for (const evt of state.trade.marketEvents) {
308	    if (evt.goodId === goodId) {
309	      mod *= evt.priceMod;
310	    }
311	  }
312	  return mod;
