318	function getSkillBuyDiscount(state) {
319	  const salesLevel = state.skills?.sales?.level || 0;
320	  // 每级销售技能降低0.3%买入价，最多30%
321	  return Math.max(0.7, 1 - salesLevel * 0.003);
322	}
323	
324	/** 销售技能对卖出价格的加成（提高卖出价） */
325	function getSkillSellBonus(state) {
326	  const salesLevel = state.skills?.sales?.level || 0;
327	  // 每级销售技能提高0.3%卖出价，最多30%
328	  return Math.min(1.3, 1 + salesLevel * 0.003);
329	}
330	
331	/** 获取技能等级能看到的额外价格信息 */
332	function getSkillPriceInfoLevel(state) {
333	  const salesLevel = state.skills?.sales?.level || 0;
334	  if (salesLevel >= 50) return 3; // 完整信息：全城最低/最高+利润预估
335	  if (salesLevel >= 25) return 2; // 部分信息：知道哪里便宜/贵
336	  if (salesLevel >= 10) return 1; // 基础信息：知道当前是贵还是便宜
337	  return 0; // 无额外信息
338	}
339	
340	// ====== 综合定价引擎 ======
341	
342	/** 计算某商品在某地的最终零售价（所有因素叠加） */
343	function calcFinalPrice(state, locKey, goodId) {
344	  const good = typeof getGoodById === "function" ? getGoodById(goodId) : null;
345	  if (!good) return 1;
346	
347	  let price = good.basePrice;
348	
349	  // 1. 地点基础价格修正
350	  price *= getLocationPriceModifier(locKey, goodId);
351	
352	  // 2. 供需修正
353	  price *= getSupplyDemandPriceMod(state, locKey, goodId);
354	
355	  // 3. 市场事件修正
356	  price *= getMarketEventPriceMod(state, goodId);
357	
358	  // 4. 天气修正
359	  if (typeof getWeatherGoodPriceMod === "function") {
360	    price *= getWeatherGoodPriceMod(state, goodId);
361	  }
362	
363	  // 5. 价格范围限制（基准价的20%-600%）
364	  price = Math.max(good.basePrice * 0.2, Math.min(good.basePrice * 6, price));
365	
366	  return Math.round(price * 100) / 100;
367	}
